# Generates OrbitalBuiltInCatalog.h (catalog, mission, assembly rules, reference builds) from PART_CATALOG.json.
import json, sys
cat = json.load(open(sys.argv[1]))
def s(x): return json.dumps("" if x is None else x)
def ids(l): return "{" + ",".join(s(i) for i in (l or [])) + "}"
def num(x): return repr(float(x))
o=['#pragma once\n// Generated by Tools/StandaloneTests/gen_data.py from Docs/CLAUDE_RESEARCH/PART_CATALOG.json (schema 2.1). Do not edit.\n// TEMPORARY: compiled-in catalog so isa/assembly runs before the JSON loader (ram/engineering) is merged.\n#include "OrbitalAssembly.h"\n#include <map>\nnamespace OrbitalData {\nusing namespace Orbital;\n']
o.append('inline Catalog MakeCatalog(){ Catalog c;\n')
F={'mass_kg':'massKg','cost_mcr':'costMCr','power_w':'powerW','base_power_w':'basePowerW','prop_capacity_kg':'capacityKg','isp_s':'ispS','max_wet_mass_kg':'maxWetMassKg','area_m2':'areaM2','capacity_wh':'capacityWh','data_gb_per_day':'dataGBPerDay','data_rate_mbps':'dataRateMbps','storage_gb':'storageGB','isp_sl_s':'seaLevelIspS','isp_vac_s':'vacuumIspS','thrust_sl_n':'seaLevelThrustN','thrust_vac_n':'vacuumThrustN','max_payload_kg':'maxPayloadKg','thrust_n':'thrustN'}
for p in cat['parts']:
    o.append(f' {{Part p; p.slot={s(p["slot"])}; p.objective={s(p.get("objective",""))};')
    for k,f in F.items():
        if k in p: o.append(f' p.{f}={num(p[k])};')
    if 'max_instruments' in p: o.append(f' p.maxInstruments={int(p["max_instruments"])};')
    if 'max_count' in p: o.append(f' p.maxCount={int(p["max_count"])};')
    o.append(f' p.needsFinePointing={"true" if p.get("needs_fine_pointing") else "false"}; p.fitsBus={ids(p.get("fits_bus"))}; p.missionModes={ids(p.get("mission_modes"))}; c.emplace({s(p["id"])},p);}}\n')
o.append(' return c;}\n')
M=cat['mission'];C=M['constants'];A=M['assumptions']
o.append('inline Mission MakeMission(){ Mission m; m.mode='+s(M['mode'])+';\n')
for f,v in [('g0',C['g0']),('earthMu',C['mu_earth']),('moonMu',C['mu_moon']),('earthRadiusM',C['r_earth_m']),('moonRadiusM',C['r_moon_m']),('moonSemiMajorAxisM',C['a_moon_m']),('solarWm2',C['solar_w_m2']),('leoAltM',A['leo_alt_m']),('ascentDeltaV',A['dv_ascent_mps']),('correctionDeltaV',A['dv_mcc_mps']),('deltaVMargin',A['dv_margin']),('cellEfficiency',A['cell_eff']),('pointingFactor',A['point_loss']),('depthOfDischarge',A['dod']),('chargeEfficiency',A['chg_eff']),('minLiftoffTwr',A['min_twr_liftoff']),('minStage2Twr',A['min_twr_stage2']),('orbitVisible',A['orbit_visible']),('opsBaseCostPerYear',A['ops_base_cost_per_year']),('primaryPass',A['primary_pass'])]:
    o.append(f' m.{f}={num(v)};')
for k,v in M['orbits'].items():
    o.append(f'\n {{Orbit ob; ob.periM={num(v["hp_m"])}; ob.apoM={num(v["ha_m"])}; ob.stationKeepingMpsPerYear={num(v["sk_mps_per_year"])};')
    for ok,ov in v['factor'].items(): o.append(f' ob.objectiveFactors[{s(ok)}]={num(ov)};')
    o.append(f' m.orbits[{s(k)}]=ob;}}')
for k,v in M['ground'].items():
    o.append(f'\n m.ground[{s(k)}]=GroundNetwork{{{num(v["hours"])},{num(v["cost_per_year"])},{num(v["max_gap_h"])}}};')
for k,v in M['budget_mcr'].items(): o.append(f' m.budgets[{s(k)}]={num(v)};')
for k,v in M['objectives'].items(): o.append(f' m.objectiveWeights[{s(k)}]={num(v["weight"])};')
for k,v in M['socket_limits'].items(): o.append(f' m.socketLimits[{s(k)}]={int(v)};')
o.append('\n m.requiredProbeSlots='+ids(M['required_probe_slots'])+';')
o.append(' m.plannedYearsOptions={'+",".join(num(x) for x in A['planned_years_options'])+'};')
o.append(' return m;}\n')
o.append('inline AssemblyRules MakeRules(){ AssemblyRules r; r.defaultOrbit='+s(M['default_orbit'])+';')
for k,v in M['socket_tree'].items(): o.append(f' r.socketTree[{s(k)}]={ids(v)};')
o.append(' return r;}\n')
o.append('inline std::map<Id,SpacecraftDesign> SpacecraftPresets(){ std::map<Id,SpacecraftDesign> p;\n')
for k,v in cat['reference_builds'].items():
    if 'bus' in v:
        o.append(f' {{SpacecraftDesign d; d.bus={s(v["bus"])}; d.engine={s(v["engine"])}; d.antenna={s(v["antenna"])}; d.computer={s(v["computer"])}; d.orbit={s(v["orbit"])}; d.ground={s(v["ground"])}; d.tanks={ids(v["tanks"])}; d.adcs={ids(v["adcs"])}; d.solar={ids(v["solar"])}; d.battery={ids(v["battery"])}; d.instruments={ids(v["instruments"])}; d.propKg={num(v["prop_kg"])}; d.years={num(v["years"])}; p[{s(k)}]=d;}}\n')
o.append(' return p;}\ninline std::map<Id,LauncherDesign> LauncherPresets(){ std::map<Id,LauncherDesign> p;\n')
for k,v in cat['reference_builds'].items():
    if 'bus' not in v:
        o.append(f' {{LauncherDesign d; d.firstTank={s(v["s1_tank"])}; d.firstEngine={s(v["s1_engine"])}; d.firstEngineCount={int(v["s1_count"])}; d.secondTank={s(v["s2_tank"])}; d.secondEngine={s(v["s2_engine"])}; d.fairing={s(v["fairing"])}; p[{s(k)}]=d;}}\n')
o.append(' return p;}\n')
o.append('} // namespace OrbitalData\n')
open(sys.argv[2],'w').write("".join(o))
